// Cross-SDK vectors generated by the Rust SDK (`wharfedale-sdk-rs/tests/vectors.json`).
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import * as liquid from 'liquidjs-lib';
import { Key, feeAssetFor, contractAddress, contractControlBlock, contractScriptPubkey, sigAllHash, parseTxOut, hex, fromHex } from '../../src/index.js';

const vectors = JSON.parse(readFileSync(new URL('../../../test/vectors.json', import.meta.url), 'utf8'));

test('keys and addresses', () => {
  for (const v of vectors.keys) {
    const k = Key.fromSecret(v.secret);
    assert.equal(hex(k.xOnlyPublicKey()), v.xonly_public_key);
    assert.equal(hex(k.scriptPubkey()), v.script_pubkey);
    assert.equal(hex(k.blindingKey()), v.blinding_key);
    assert.equal(hex(k.blindingPublicKey()), v.blinding_public_key);
    assert.equal(k.address(), v.address);
    assert.equal(k.explicitAddress(), v.explicit_address);
  }
});

test('fee assets', () => {
  for (const v of vectors.fee_assets) assert.equal(feeAssetFor(v.chain_id), v.fee_asset);
});

test('contract outputs from a CMR', () => {
  for (const v of vectors.contracts) {
    const cmr = fromHex(v.cmr);
    assert.equal(hex(contractScriptPubkey(cmr)), v.script_pubkey, v.name);
    assert.equal(hex(contractControlBlock(cmr)), v.control_block, v.name);
    assert.equal(contractAddress(cmr), v.address, v.name);
    assert.equal(v.artifact.cmr, v.cmr);
  }
});

test('sig_all_hash matches rust-simplicity', () => {
  for (const v of vectors.sig_all_hash) {
    const tx = liquid.Transaction.fromHex(v.tx);
    const prevouts = v.prevouts.map((p: string) => parseTxOut(fromHex(p)));
    assert.equal(hex(sigAllHash(tx, prevouts, v.ix, fromHex(v.cmr), v.genesis_hash)), v.sig_all_hash, v.name);
  }
});
